<script lang="ts">import { onMount } from 'svelte'; import { api } from '$lib/api'; import type { Guardian, Student } from '$lib/types'; let guardians:Guardian[]=[];let students:Student[]=[];let error='';let notice='';let form={firstName:'',lastName:'',email:'',phone:'',studentIds:[] as string[]};async function load(){try{[guardians,students]=await Promise.all([api<Guardian[]>('/api/guardians'),api<Student[]>('/api/students')]);}catch(e){error=e instanceof Error?e.message:'Could not load guardians.';}}async function create(){try{await api('/api/guardians',{method:'POST',body:JSON.stringify(form)});notice='Guardian created and linked.';form={firstName:'',lastName:'',email:'',phone:'',studentIds:[]};await load();}catch(e){error=e instanceof Error?e.message:'Could not create guardian.';}}onMount(load);</script>
<div class="toolbar"><div><span class="eyebrow">PEOPLE</span><h2>Guardians</h2></div></div>{#if error}<div class="error">{error}</div>{/if}{#if notice}<div class="status">{notice}</div>{/if}<section class="card"><h3>Create guardian and link students</h3><form class="form-grid" on:submit|preventDefault={create}><label>First name<input bind:value={form.firstName} required /></label><label>Last name<input bind:value={form.lastName} required /></label><label>Email<input type="email" bind:value={form.email} required /></label><label>Phone<input bind:value={form.phone} /></label><label class="full">Students<select multiple bind:value={form.studentIds}>{#each students as student}<option value={student.id}>{student.firstName} {student.lastName}</option>{/each}</select></label><div class="full"><button class="button">Save guardian</button></div></form></section><section class="card"><h3>Guardian records</h3><div class="table-wrap"><table><thead><tr><th>Name</th><th>Contact</th><th>Linked students</th></tr></thead><tbody>{#each guardians as guardian}<tr><td>{guardian.firstName} {guardian.lastName}</td><td>{guardian.email}<br />{guardian.phone||''}</td><td>{guardian.students.map(x=>x.name).join(', ')||'None linked'}</td></tr>{:else}<tr><td colspan="3" class="muted">No guardians yet.</td></tr>{/each}</tbody></table></div></section>
